CREATE TABLE public.bot_verified_payments (order_id uuid PRIMARY KEY REFERENCES public.bot_orders(id), submission_id uuid NOT NULL REFERENCES public.bot_payment_submissions(id), verified_by uuid NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), amount numeric(12,2) NOT NULL); GRANT ALL ON public.bot_verified_payments TO service_role; ALTER TABLE public.bot_verified_payments ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.record_verified_bot_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='paid' AND OLD.status='under_review' THEN INSERT INTO public.bot_verified_payments(order_id,submission_id,verified_by,amount) SELECT NEW.id,id,auth.uid(),NEW.amount FROM public.bot_payment_submissions WHERE order_id=NEW.id ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER bot_verified_record AFTER UPDATE OF status ON public.bot_orders FOR EACH ROW EXECUTE FUNCTION public.record_verified_bot_payment();
CREATE OR REPLACE FUNCTION public.reject_stale_bot_payments() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN WITH stale AS (UPDATE public.bot_orders o SET status='rejected',reason='Payment not received!' FROM public.bot_payment_submissions p WHERE o.id=p.order_id AND o.status='under_review' AND p.submitted_at<=now()-interval '10 minutes' RETURNING o.id) INSERT INTO public.bot_audit(action,details) SELECT 'payment_timeout',jsonb_build_object('order',id) FROM stale; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.reject_stale_bot_payments() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reject_stale_bot_payments() TO service_role;
CREATE OR REPLACE FUNCTION public.reject_stale_payments() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE affected integer; BEGIN UPDATE public.payments SET status='rejected',rejection_reason='Payment not received!',reviewed_at=now() WHERE status IN ('pending_review','under_verification') AND created_at<now()-interval '10 minutes'; GET DIAGNOSTICS affected=ROW_COUNT; RETURN affected+public.reject_stale_bot_payments(); END $$;
CREATE OR REPLACE FUNCTION public.submit_bot_payment(_order uuid,_method uuid,_reference text,_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.bot_orders; m public.payment_methods; BEGIN SELECT * INTO o FROM public.bot_orders WHERE id=_order AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF o.status='under_review' THEN RETURN; END IF; IF o.status<>'awaiting_payment' THEN RAISE EXCEPTION 'Order cannot accept payment'; END IF; SELECT * INTO m FROM public.payment_methods WHERE id=_method AND enabled AND (address IS NOT NULL OR qr_image_url IS NOT NULL); IF NOT FOUND OR length(trim(_reference))<3 OR length(_reference)>200 THEN RAISE EXCEPTION 'Valid payment method and reference required'; END IF; IF nullif(_proof,'') IS NOT NULL AND (_proof NOT LIKE auth.uid()::text || '/' || _order::text || '/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='bot-order-proofs' AND name=_proof)) THEN RAISE EXCEPTION 'Invalid proof'; END IF; INSERT INTO public.bot_payment_submissions(order_id,method_id,method_name,transaction_reference,proof_path) VALUES(o.id,m.id,m.name,trim(_reference),nullif(_proof,'')); UPDATE public.bot_orders SET status='under_review' WHERE id=o.id; INSERT INTO public.bot_audit(actor,action,details) VALUES(auth.uid(),'payment_submitted',jsonb_build_object('order',o.id)); END $$;
CREATE OR REPLACE FUNCTION public.reject_bot_review_after_deadline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.status='under_review' AND NEW.status='paid' AND EXISTS(SELECT 1 FROM public.bot_payment_submissions WHERE order_id=OLD.id AND submitted_at<=now()-interval '10 minutes') THEN RAISE EXCEPTION 'Review deadline passed. Payment not received!'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bot_review_deadline BEFORE UPDATE OF status ON public.bot_orders FOR EACH ROW EXECUTE FUNCTION public.reject_bot_review_after_deadline();